window.addEventListener("DOMContentLoaded",(()=>{document.querySelectorAll(".hero__label").forEach((e=>{const r=e.querySelector(".hero__input"),t=e.querySelector(".hero__placeholder");r.addEventListener("focus",(()=>{t.classList.add("active")})),r.addEventListener("blur",(()=>{""===r.value.trim()&&t.classList.remove("active")}))})),document.querySelector(".hero__form").addEventListener("submit",(function(e){let r=!0;this.querySelectorAll(".hero__label").forEach((e=>{e.querySelector(".hero__input").checkValidity()?e.classList.remove("error"):(e.classList.add("error"),r=!1)}))}))}));